insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('prms', 'advanced', 'module', 'm01-arithmetic-aggregation', 1, 'The Ekene Reserves aggregation (synthetic) holds EKN-1, EKN-2 and EKN-U at the field level in MMbbl. What arithmetic 1P does the engine return?', '["26.396958, the best estimates added", "8.890000, EKN-1''s low estimate alone", "15.809794, the three low estimates added", "26.821102, the sum of the three project means read off each distribution"]'::jsonb, 2, 'The arithmetic 1P adds the low estimates: 8.890000, 3.945035 and 2.974759 give 15.809794 (engine). 26.396958 is the arithmetic 2P, the sum of the best estimates; 8.890000 is EKN-1 on its own; 26.821102 is the exact sum of the means, which belongs beside the best estimates and is no category.'),
  ('prms', 'advanced', 'module', 'm01-arithmetic-aggregation', 2, 'Adding the high estimates of the three Ekene Reserves projects gives which arithmetic 3P?', '["38.387162, the three high estimates added category by category", "24.990000, the high estimate of EKN-1 on its own", "36.465253, the sampled high of the total", "26.396958, taken from the best estimates"]'::jsonb, 0, 'The arithmetic 3P adds the high estimates of EKN-1, EKN-2 and EKN-U: 24.990000, 8.371921 and 5.025241 give 38.387162 (engine). 24.990000 leaves out two projects; 36.465253 is a Monte Carlo figure on seed 20271112 and 20000 draws and no arithmetic sum; 26.396958 is the arithmetic 2P.'),
  ('prms', 'advanced', 'module', 'm01-arithmetic-aggregation', 3, 'How does the engine''s arithmetic aggregation build the total of several projects of one class?', '["It adds each project''s mean and prints that one sum in the 1P, the 2P and the 3P rows alike", "It samples the stated distributions on the stated seed and reads the 0.1 quantile of the totals as 1P", "It weights each project''s estimates by its share of the field total before adding the categories", "It adds the lows for the total low, the bests for the total best and the highs for the total high (PRMS 4.2.5.2)"]'::jsonb, 3, 'Arithmetic aggregation is summation category by category (PRMS 4.2.5.2): low with low, best with best, high with high. A sum of means is printed separately and fills no category; sampling on a seed is the statistical aggregation beside it; no weighting by share enters the sum.'),
  ('prms', 'advanced', 'module', 'm01-arithmetic-aggregation', 4, 'The same three Ekene Reserves projects are aggregated once at the "field" level and once at the "above-field" level. What does the engine report as reportable at each?', '["\"statistical\" at the field level; \"arithmetic-or-statistical\" above it", "\"arithmetic-or-statistical\" at the field level; \"arithmetic\" above it", "\"arithmetic\" at both levels, since these are Reserves in both calls", "\"arithmetic-or-statistical\" at both levels, since correlation is stated"]'::jsonb, 1, 'At the field, property or project level statistical aggregation may be reported (PRMS 4.2.5.4), so the engine returns "arithmetic-or-statistical"; above the field level it returns "arithmetic". The class does not set the answer, and a stated correlation does not lift the above-field restriction. No call returns "statistical" alone.'),
  ('prms', 'advanced', 'module', 'm01-arithmetic-aggregation', 5, 'Between the field-level and above-field-level calls on the Ekene Reserves, which of the engine''s figures change?', '["The arithmetic 1P falls above the field level, because the engine applies the conservative caution", "None: the sums and the sampled figures are the same, and only what may be reported differs", "The sampled P90 moves onto the arithmetic 1P above the field level", "The arithmetic 3P rises above the field level, since the high estimates are then treated as dependent"]'::jsonb, 1, 'Both calls return an arithmetic 1P of 15.809794 and a sampled P90 of 17.300834 on seed 20271112 and 20000 draws (engine); the level changes only the reportable field. The caution about a conservative 1P and an optimistic 3P is a sentence the engine prints, and it moves no figure; sampling runs at both levels.'),
  ('prms', 'advanced', 'module', 'm01-arithmetic-aggregation', 6, 'Above the field level the engine prints a caution beside the arithmetic sums (PRMS 4.2.5.4). What does it say about them?', '["the aggregate 1P may be very optimistic and the aggregate 3P very conservative, so the statistical figures replace them", "the aggregate 2P is biased low whenever the projects are correlated, so the sum of means is reported beside it", "the arithmetic sums may be reported only when every stated correlation is 0, so the call is refused otherwise", "the aggregate 1P may be very conservative and the aggregate 3P very optimistic, with the statistical figures kept for portfolio analysis"]'::jsonb, 3, 'The engine''s own words are that the aggregate 1P may be very conservative and the aggregate 3P very optimistic, and that the statistical figures serve portfolio analysis (PRMS 4.2.5.5). The reversed caution has the direction wrong; nothing is said about a biased 2P; and a stated correlation never causes a refusal of the arithmetic sums.'),
  ('prms', 'advanced', 'module', 'm01-arithmetic-aggregation', 7, '17 CFR 229.1202(a)(3) (the eCFR current at 2026-09-01) is quoted in this course. What does it require of reported total reserves?', '["simple arithmetic sums of the property or field estimates within each reserves category", "a probabilistic company-level total, its 0.1 quantile reported as proved", "a sum of the project means, reported as the 2P", "a risked total, with each field multiplied by its chance of commerciality before the categories are added"]'::jsonb, 0, 'Item 1202(a)(3) of Regulation S-K requires reported totals to be simple arithmetic sums of the estimates for individual properties or fields within each category. It does not call for a company-level probabilistic total, a sum of means as 2P, or a risked total: Reserves carry no chance figure.'),
  ('prms', 'advanced', 'module', 'm01-arithmetic-aggregation', 8, 'Which limit on probabilistic methods does paragraph (a)(3) of Item 1202 of Regulation S-K (17 CFR 229.1202, the eCFR current at 2026-09-01) set?', '["Probabilistic aggregation is required at the company level whenever more than two fields are reported", "Probabilistic totals may be reported at any level when the correlation between fields is stated as 0", "Reserves are not aggregated probabilistically beyond the field or property level", "Probabilistic methods may be used only for Contingent Resources"]'::jsonb, 2, 'The rule stops probabilistic aggregation at the field or property level and adds arithmetically above it, which is why the engine reports "arithmetic" above the field. It requires no company-level probabilistic total, grants no exception for a correlation of 0, and says nothing about Contingent Resources.'),
  ('prms', 'advanced', 'module', 'm01-arithmetic-aggregation', 9, 'The engine prints the same sentence in every aggregate call about a sum of low estimates. When is the arithmetic 1P also the P90 of the total?', '["Whenever the projects are independent, since independent errors cancel out in the sum", "Whenever every project states a normal distribution, because sums of normals are normal", "Whenever the level is above the field, since the SEC rule makes the two figures equal", "Only when every project is totally dependent, so that when one comes in low they all do"]'::jsonb, 3, 'The engine''s reason says the arithmetic sum of the low estimates is the P90 of the total only when every project is totally dependent (PRMS 4.2.5.2). Independence moves the sampled low away from it; a sum of normals is normal but its low is still above the sum of the lows; and the level decides what is reported without changing either figure.'),
  ('prms', 'advanced', 'module', 'm01-arithmetic-aggregation', 10, 'With the pairs as stated for Ekene (seed 20271112, 20000 draws), is the sampled low of the total above, below or on the sum of the three low estimates, 15.809794?', '["Below it, since sampling spreads the total wider than the sum does", "Above it, and the engine prints the gap in its reasons", "Exactly on it, because the correlations were stated for all three pairs", "It cannot be said, because the engine prints the sampled figures only above the field"]'::jsonb, 1, 'The sampled P90 on that seed and those draws is 17.300834, above 15.809794, and the engine''s reason states that the statistical low exceeds the arithmetic one. A sum of lows sits below the low of a partly independent total; stating every pair does not make them totally dependent; and the sampled figures are printed at both levels.'),
  ('prms', 'advanced', 'module', 'm01-arithmetic-aggregation', 11, 'A fourth project, EKN-C, is added to the Ekene Reserves with low, best and high all equal to 1.200000. What arithmetic 1P does the engine return?', '["17.009794: the constant adds its value to every category", "15.809794: a constant carries no range and is left out of the sums", "17.300834: the sampled low of the total, since a constant adds nothing to it", "a refusal: a constant is no distribution the engine can sample or add"]'::jsonb, 0, 'Equal low, best and high make EKN-C a constant, which adds 1.200000 to every draw and to every arithmetic category: 15.809794 becomes 17.009794 (engine). It is neither dropped nor refused; 17.300834 is the sampled low without the constant, on seed 20271112 and 20000 draws, and the constant moves the sampled figures too.'),
  ('prms', 'advanced', 'module', 'm01-arithmetic-aggregation', 12, 'EKN-2 states a lognormal distribution with a mean of 6.000000 and a standard deviation of 1.800000. What low estimate does the engine read off it for the arithmetic sum?', '["6.000000", "5.746958", "3.945035", "8.371921"]'::jsonb, 2, 'The engine reads the low estimate of a stated lognormal with the closed-form readers of lib/stats: 3.945035 (engine). 6.000000 is its mean; 5.746958 is its best estimate, which sits below the mean for a lognormal; 8.371921 is its high estimate.'),
  ('prms', 'advanced', 'module', 'm01-arithmetic-aggregation', 13, 'EKN-1 states low, best and high of 8.890000, 16.650000 and 24.990000 as a "triangular-fit". What mode does the fitted triangular carry?', '["16.650000, the fitted mode equals the stated best", "16.821102, which is the mean the engine reads off the fitted distribution", "16.097684, which differs from the stated best of 16.650000", "31.737202, the fitted maximum, which a triangular fit places at its mode"]'::jsonb, 2, 'The engine fits a triangular through the three stated estimates with lib/stats and returns min 2.628420, mode 16.097684 and max 31.737202; the best estimate is its median, 16.650000, and its mean is 16.821102. The mode of a skewed triangular is neither its median nor its mean, and the maximum is a separate parameter.'),
  ('prms', 'advanced', 'module', 'm01-arithmetic-aggregation', 14, 'The Ekene Reserves are run under four stated correlations: uniform 0, the stated pairs, uniform 0.95 and uniform -0.4. What happens to the arithmetic 1P?', '["It falls toward the sampled low as the stated correlation rises from 0 to 0.95", "It rises under the negative correlation, because the projects offset one another", "It is recomputed from the sampled low of each run and so differs a little each time", "It stays 15.809794 on every run, since a sum of lows reads no correlation"]'::jsonb, 3, 'The arithmetic sum does not read the correlation: every run returns 15.809794 as its arithmetic 1P and 38.387162 as its 3P (engine). It is the sampled low that moves with the correlation; the arithmetic figures are closed-form sums of the stated estimates and use no draw.'),
  ('prms', 'advanced', 'module', 'm01-arithmetic-aggregation', 15, 'A reserves report quotes the Ekene figure 15.809794. Which description fits the vocabulary this course legislates?', '["the arithmetic 1P of the Ekene Reserves at the field level, in MMbbl, a sum of low estimates", "the P90 of the Ekene field, in MMbbl, which has a 90 percent chance of being met or exceeded", "the proved reserves of the Ekene field, meaning the quantities shown true at the field level", "the risked Ekene Reserves in MMbbl, since each project''s low estimate already carries a chance"]'::jsonb, 0, 'A figure is quoted with its class, unit and method, and this one is an arithmetic sum of low estimates. It is no P90 of the total, because the projects are not totally dependent; "proved" means the cumulative 1P, and a proof of truth is no part of it; and Reserves carry no chance, so "risked" does not apply.'),
  ('prms', 'advanced', 'module', 'm02-probabilistic-aggregation', 1, 'Where does the sampler behind the engine''s statistical aggregation come from?', '["A sampler written inside prms.js for reserves work alone, seeded from the project count and the stated unit", "lib/stats: createCorrelatedSampler (a Gaussian copula with a Cholesky factor) on the mulberry32 generator", "engines/economics/cashflow.ts, which the engine already imports for computeCashFlow and applyJV", "The panel''s own browser random numbers, drawn afresh each time the aggregation calculator is opened"]'::jsonb, 1, 'The engine''s basis names lib/stats/stats.js: createCorrelatedSampler (Gaussian copula, Cholesky), mulberry32, fitTriangularToPercentiles and quantile. prms.js carries no sampler of its own; cashflow.ts supplies the cash flow and applyJV and no sampler; and a panel reproduces its figures because the draws are seeded.'),
  ('prms', 'advanced', 'module', 'm02-probabilistic-aggregation', 2, 'How does the engine read the low estimate of a total from its sampled draws?', '["As the 0.9 quantile of the totals, since P90 names the 90th percentile of the sampled draws", "As the sum of each project''s own low estimate, each read off its stated distribution first", "As the mean of the totals less a multiple of their sampled standard deviation", "As the 0.1 quantile of the totals, labelled P90 per lib/conventions/percentile.js"]'::jsonb, 3, 'The engine''s label line reads that P90 is the 0.1 quantile of the totals, the low estimate, per lib/conventions/percentile.js; the 0.9 quantile is the alternative that would read P90 as high. A sum of lows is the arithmetic 1P, a different figure; and no normal approximation of the total is made.'),
  ('prms', 'advanced', 'module', 'm02-probabilistic-aggregation', 3, 'The Ekene Reserves are sampled on seed 20271112 with 20000 draws, then again on the same seed and draws, then on seed 20271113 with 20000 draws. What does that show?', '["The same seed and draws give the same P90 again; a new seed moves it, so a sampled figure is quoted with both and is not graded", "The sampler is broken, because a correct Monte Carlo returns one P90 on every seed", "The second seed is the better one, because its P90 lies closer to the arithmetic 1P", "The draws are too few, and at 200000 draws every seed returns the same P90 exactly"]'::jsonb, 0, 'On seed 20271112 the P90 is 17.300834 on both runs; on seed 20271113 it is 17.414533 (engine, 20000 draws each). Every seeded Monte Carlo moves with its seed by the sampling error; no seed is better; and more draws narrow the sampling error without removing it: at 200000 draws on seed 2011 the independent P90 of the 2011 Guidelines'' two blocks still sits 0.030852 from the exact low (engine).'),
  ('prms', 'advanced', 'module', 'm02-probabilistic-aggregation', 4, 'The Ekene Reserves are sampled on seed 20271112 and 20000 draws under uniform 0, the stated pairs and uniform 0.95. What does the sampled P90 do as the stated correlation rises?', '["It rises away from the arithmetic 1P", "It stays at 17.300834 on all three runs", "It falls toward the arithmetic 1P of 15.809794", "It falls below the arithmetic 1P at uniform 0.95, crossing it"]'::jsonb, 2, 'On those draws the P90 runs 18.487436, 17.300834 and 15.891238 (engine): it moves toward 15.809794 as the correlation rises and stays above it at 0.95. It does not rise; it moves with every run; and it does not cross the arithmetic sum, which is the P90 only under total dependence.'),
  ('prms', 'advanced', 'module', 'm02-probabilistic-aggregation', 5, 'Of the four stated correlations run on the Ekene Reserves (seed 20271112, 20000 draws), which puts the sampled P90 furthest above the arithmetic 1P?', '["uniform -0.4, where the projects offset one another most", "uniform 0.95, since a strong correlation widens the total", "uniform 0, since independent projects sit furthest apart", "the stated pairs, which are the only unequal correlations"]'::jsonb, 0, 'The sampled P90 is 20.009881 under uniform -0.4, 18.487436 under 0, 17.300834 under the stated pairs and 15.891238 under 0.95 (engine, on that seed and those draws). A negative correlation lets a low project be offset by a high one, lifting the low of the total furthest; strong positive correlation pulls it toward the sum of the lows.'),
  ('prms', 'advanced', 'module', 'm02-probabilistic-aggregation', 6, 'On every one of those four Ekene Reserves runs, what exact mean of the total does the engine print beside the sampled mean?', '["26.699904, the sampled mean of the stated-pairs run on seed 20271112", "26.821102, the sum of the three means", "26.396958, the arithmetic 2P", "26.430497, the sampled P50 of the stated-pairs run, being the best of the total"]'::jsonb, 1, 'The mean of a total is the sum of the means whatever the correlation (PRMS 4.2.5.2), so the exact 26.821102 is printed on every run (engine). 26.699904 is a sampled mean on seed 20271112 and 20000 draws; 26.396958 sums best estimates, which are medians of each project; 26.430497 is a sampled P50.'),
  ('prms', 'advanced', 'module', 'm02-probabilistic-aggregation', 7, 'The 2011 Guidelines'' blocks A and B, read as normals with means 53.400000 and 35.600000, have 90 percent half-widths of 10.100000 and 7.100000. What is the exact low of their sum when they are independent?', '["71.800000", "76.623299", "76.434906", "76.654150"]'::jsonb, 3, 'For two independent normals the low of the sum is 89.000000 less the square root of the sum of the squared half-widths: 76.654150 (derived, in closed form). 71.800000 is the arithmetic sum of the lows; 76.623299 is the sampled P90 on seed 2011 and 200000 draws; 76.434906 is the sampled P90 of the same blocks read as lognormals.'),
  ('prms', 'advanced', 'module', 'm02-probabilistic-aggregation', 8, 'Under the Guidelines'' own symmetric reading taken by the golden input, what standard deviation does block A carry (expectation 53.400000, Proved 43.300000)?', '["10.100000: the half-width itself, the gap between the expectation and the Proved", "8.289303: the standard deviation of a lognormal through the same expectation and Proved", "7.881072: the half-width of 10.100000 over the standard normal 90th percentile", "5.540159"]'::jsonb, 2, 'The golden input reads each block as a normal with the expectation as its mean and the expectation less the Proved as its 90 percent half-width, so its standard deviation is 10.100000 over the standard normal 90th percentile: 7.881072. 10.100000 is the half-width; 8.289303 belongs to the lognormal reading; 5.540159 is block B''s standard deviation.'),
  ('prms', 'advanced', 'module', 'm02-probabilistic-aggregation', 9, 'The same two blocks are sampled at a stated correlation of 0.999 on seed 2011 and 200000 draws. What happens to the sampled P90?', '["It stays near the independent figure of 77 that the Guidelines print", "It returns almost to the arithmetic sum of the lows, 71.800000", "The call is refused, because 0.999 is treated as total dependence", "It rises above the exact independent low of 76.654150"]'::jsonb, 1, 'Near total dependence the sampled P90 is 71.774133 (engine, on that seed and those draws), almost the arithmetic 71.800000: a sum of lows is the low of the total when the parts move together. 0.999 is accepted (a correlation of 1 is refused); the independent figure belongs to correlation 0.'),
  ('prms', 'advanced', 'module', 'm02-probabilistic-aggregation', 10, 'Read as lognormals through the same expectations and Proved figures, the Guidelines'' blocks give a sampled P90 of 76.434906 on seed 2011 and 200000 draws, against 76.623299 for the normal reading on the same seed and draws. What does the pair teach?', '["The stated marginal distribution moves the probabilistic total, so the reading is named beside the figure", "The lognormal reading is wrong, since the Guidelines print 77 and only the normal reading comes close to it", "The two readings agree once rounded to whole numbers, so the choice of distribution does not matter to a total", "The seed differs between the two runs, which accounts for the whole of the gap between the two sampled figures"]'::jsonb, 0, 'Both runs use seed 2011 and 200000 draws; the gap comes from the marginals. The Guidelines add their blocks for symmetric distributions and the golden input takes that reading, stated as such; the course names both and grades neither. Rounding to 77 hides the difference without removing it.'),
  ('prms', 'advanced', 'module', 'm02-probabilistic-aggregation', 11, 'A caller states a uniform correlation of 1 between the Ekene projects. What does the engine return?', '["the arithmetic sums returned as the sampled figures, since total dependence makes the two methods agree exactly and no draw is then needed at all", "a result with the correlation capped at 0.999 and a warning line in the reasons", "the refusal: correlation must be a positive semidefinite correlation matrix; got 1", "the refusal: correlation.rho must be a number above -1 and below 1 (the canonical sampler takes a correlation strictly between -1 and 1); got 1"]'::jsonb, 3, 'The engine refuses a rho of 1 by name, in its own words: correlation.rho must be a number above -1 and below 1 (the canonical sampler takes a correlation strictly between -1 and 1); got 1. It substitutes no arithmetic answer and caps nothing; the positive semidefinite refusal is a different message for a matrix the Cholesky factor cannot reproduce.'),
  ('prms', 'advanced', 'module', 'm02-probabilistic-aggregation', 12, 'Three varying projects are given a uniform correlation of -0.6. What does the engine return, in its own words?', '["correlation.rho must be a number above -1 and below 1 (the canonical sampler takes a correlation strictly between -1 and 1); got -0.6", "a sampled total with the correlation clipped to 0 and a line saying the matrix was adjusted", "correlation must be an object { type: \"uniform\", rho } or { type: \"pairs\", pairs } (stated; no default); got -0.6", "correlation must be a positive semidefinite correlation matrix (the Cholesky factor misses the stated matrix by 0.8); got {\"type\":\"uniform\",\"rho\":-0.6}"]'::jsonb, 3, 'Three variables cannot all be correlated at -0.6: the matrix is not positive semidefinite and the engine refuses it, naming how far the Cholesky factor misses (0.8). -0.6 is inside the range the rho check allows, so that message does not fire; nothing is clipped or adjusted; and the object-shape message is for a correlation left out.'),
  ('prms', 'advanced', 'module', 'm02-probabilistic-aggregation', 13, 'A pairs correlation on the three Ekene Reserves projects states only two pairs. What does the engine return?', '["a result that treats the missing pair as independent, filling it with a correlation of 0 and saying so in the reasons", "a result that copies the nearest stated correlation into the missing pair and prints the matrix it then used", "a refusal naming the first missing pair, EKN-2 and EKN-U, and asking for one pair each of the 3 pairs", "a refusal saying that correlation.pairs[2] must be a pair stated once, since a pair was entered twice by mistake"]'::jsonb, 2, 'The engine refuses: correlation.pairs must be one pair for each of the 3 pairs of varying projects, a correlation of 0 being entered as a pair like any other, and it names EKN-2 and EKN-U as the first missing pair. It supplies no 0 and copies nothing; the "stated once" refusal is for a duplicate pair.'),
  ('prms', 'advanced', 'module', 'm02-probabilistic-aggregation', 14, 'The seed is removed from an aggregation call. What does the engine return, in its own words?', '["seed must be an integer from 0 to 4294967295 (the mulberry32 seed; no default); got nothing", "a result on the seed 20271112, which the Ekene fixture uses", "a result on a seed drawn from the clock, printed in the reasons", "iterations must be an integer from 100 to 200000; got nothing"]'::jsonb, 0, 'The seed is a stated input with no default, and the engine refuses its absence by name. It borrows no fixture seed and reads no clock, which is what lets any figure be reproduced on its seed and draws; the iterations message belongs to a missing or out-of-range draw count.'),
  ('prms', 'advanced', 'module', 'm02-probabilistic-aggregation', 15, 'Which of these figures from an Expert aggregation can be a graded figure in this course?', '["the sampled P90 on the stated seed and draws", "the arithmetic 1P, a return of the engine on fixed inputs", "a Monte Carlo mean on the stated seed and draws", "the P50 of the total, since it is the best estimate"]'::jsonb, 1, 'Every graded number is a return value of the engine on fixed inputs, and none comes from the Monte Carlo. The sampled P90, P50, P10 and mean are taught with their seed and draw count, and none is graded as an exact figure; the arithmetic sums are closed-form and can be graded.'),
  ('prms', 'advanced', 'module', 'm03-risked-quantities-and-classes', 1, 'The Ekene Contingent Resources (synthetic) hold EKN-3, EKN-4 and EKN-5 with chances of commerciality of 50.000000, 65.000000 and 20.000000 percent and means of 13.000000, 4.637674 and 3.000000 MMboe. What risked mean does the engine return?', '["20.637674 MMboe, the sum of the three means with no chance applied", "13.000000 MMboe, the mean of EKN-3, the project with the largest mean", "4.637674 MMboe", "10.114488 MMboe"]'::jsonb, 3, 'The risked mean is the sum of each project''s chance of commerciality times its mean: 50.000000 percent of 13.000000, 65.000000 percent of 4.637674 and 20.000000 percent of 3.000000 add to 10.114488 MMboe (engine). 20.637674 is the unrisked sum of the means; 13.000000 is EKN-3 alone; 4.637674 is EKN-4''s unrisked mean.'),
  ('prms', 'advanced', 'module', 'm03-risked-quantities-and-classes', 2, 'How does the engine build a risked mean for a risked class?', '["It multiplies the arithmetic 2C by the average chance of the projects", "It adds, project by project, the stated chance of commerciality times the project''s mean (the 2011 Guidelines 6.4)", "It multiplies the sampled P50 of the total by the product of every project''s chance of commerciality, taken together", "It samples each project as a success or a failure on the seed and reports the mean of the risked totals"]'::jsonb, 1, 'The engine''s line reads: the sum of chance of commerciality x mean, citing PRMS 4.2.6, FAQ 6.9 and the 2011 Guidelines 6.4. It uses each project''s own chance on its own mean; a best estimate or a sampled P50 is no mean, a product of chances belongs to no project, and the risked mean is closed-form with no draw behind it.'),
  ('prms', 'advanced', 'module', 'm03-risked-quantities-and-classes', 3, 'The Ekene Prospective Resources (EKN-6 and EKN-7) are aggregated with their chances of commerciality. What risked mean does the engine return?', '["49.333333 MMbbl, since Prospective Resources carry a chance of discovery only", "8.980000 MMbbl, the same figure as the sum of means once rounded", "8.980000 MMbbl, against an unrisked sum of means of 49.333333", "20.000000 MMbbl"]'::jsonb, 2, 'The engine returns a risked mean of 8.980000 against a sum of means of 49.333333 (engine): each prospect''s chance of commerciality, Pg x Pd, times its mean. 49.333333 is the unrisked sum; the two figures differ by far more than rounding; and 20.000000 is EKN-6''s chance of commerciality in percent, which is no quantity.'),
  ('prms', 'advanced', 'module', 'm03-risked-quantities-and-classes', 4, 'A caller wants one total for the Ekene Reserves, Contingent Resources and Prospective Resources together. What does the engine allow?', '["One class a call: each class is aggregated on its own, and each figure says whether it is risked", "Every project in one call, each class weighted by its chance before the categories are summed into one", "One call with every project, the Reserves entered at a chance of commerciality of 100", "A single call once the level is set above the field, where the classes merge"]'::jsonb, 0, 'The engine aggregates the projects of one class at a time; the classes are not added into one figure (PRMS 4.2.6; FAQ 6.9; the 2011 Guidelines 6.4). No weighting merges them; a chance stated on Reserves is refused; and the level decides only what may be reported.'),
  ('prms', 'advanced', 'module', 'm03-risked-quantities-and-classes', 5, 'Chance of commerciality 100 is typed on the first project of a Reserves aggregation. How does the engine treat it?', '["a result in which the chance of 100 multiplies every mean by one, so the risked mean equals the sum of the means", "projects[0].chanceOfCommercialityPct must be a number from 0 to 100; got 100", "projects[0].chanceOfCommercialityPct must be left out for Reserves (their chance of commerciality is not a stated figure, PRMS 2.1.3.3); got 100", "a result that ignores the chance and prints a warning line saying Reserves carry none"]'::jsonb, 2, 'Reserves carry no stated chance of commerciality (PRMS 2.1.3.3), and the engine refuses one by name even at 100. It computes no risked mean for Reserves and drops no key silently; the range message is the one for a Contingent project whose chance is missing or out of range.'),
  ('prms', 'advanced', 'module', 'm03-risked-quantities-and-classes', 6, 'A Contingent Resources aggregation leaves out the chance of commerciality on its first project. What does the engine return?', '["a result that uses a chance of 100 for that project and says so in the reasons", "a result that leaves the project out of the risked mean alone and keeps it in the arithmetic sums", "projects[0].chanceOfCommercialityPct must be left out for Reserves; got nothing", "projects[0].chanceOfCommercialityPct must be a number from 0 to 100; got nothing"]'::jsonb, 3, 'A risked class carries a stated chance on every project, and a missing one is refused with the engine''s own message. No chance is supplied for it, no project is quietly dropped from the risked mean, and the "left out for Reserves" refusal belongs to the opposite case.'),
  ('prms', 'advanced', 'module', 'm03-risked-quantities-and-classes', 7, 'A project states a distribution of type "beta". What does the engine return?', '["a result that reads the beta as a triangular with the same minimum, mode and maximum as it was stated", "a refusal naming the four types it takes: \"triangular-fit\", \"triangular\", \"lognormal\", \"normal\"", "a refusal saying the distribution must be a normal whose low estimate stays at or above 0", "a result that fits a triangular through the beta''s percentiles and states the fit it made in the reasons"]'::jsonb, 1, 'The engine''s message is projects[0].distribution.type must be one of "triangular-fit", "triangular", "lognormal", "normal"; got "beta". It converts no type into another and fits nothing it was not told to fit; the normal message belongs to a normal whose low estimate falls below 0.'),
  ('prms', 'advanced', 'module', 'm03-risked-quantities-and-classes', 8, 'A "triangular-fit" project states low 10, best 15 and high 24. What does the engine return?', '["a refusal: the best estimate sits too near the low estimate for any triangular to pass through the three exactly", "a triangular whose minimum would fall below 0, refused with its fitted minimum printed", "a triangular fitted as closely as it can manage, with the miss printed as a warning line", "a result with a lognormal fitted in its place, because no triangular passes"]'::jsonb, 0, 'The engine refuses a fit it cannot make exactly: projects[0].estimates must be low, best and high that a triangular distribution passes through exactly (lib/stats fitTriangularToPercentiles), the best sitting too near the low. The below-0 refusal is a different message for a fit that passes and reaches below 0; no near-fit or substitute is returned.'),
  ('prms', 'advanced', 'module', 'm03-risked-quantities-and-classes', 9, 'Low 1, best 5 and high 9 are stated for a fitted triangular. What comes back from the engine?', '["a refusal: the fitted triangular passes through them exactly but its minimum would be -2.236068", "a refusal: the best estimate sits too near the low estimate for any triangular to pass through all three", "a result whose fitted minimum is set to 0, with the mode moved along to keep the three estimates on the fit", "a result, since the low, best and high are in order and evenly spaced about the best estimate of 5"]'::jsonb, 0, 'A fit that does pass through the three exactly and still reaches below 0 is refused with its own message, printing the minimum it would have: -2.236068 (engine). The exactness message is for a fit that cannot pass at all; the engine moves no parameter to rescue a fit; and order alone is not enough.'),
  ('prms', 'advanced', 'module', 'm03-risked-quantities-and-classes', 10, 'A project states a normal with mean 1 and standard deviation 1. What does the engine return?', '["a result whose negative draws are set to 0 before the total is read", "a refusal, because a normal is accepted only for Contingent Resources", "a refusal, because its low estimate would be -0.281552", "a result with a line in the reasons that the normal draws below 0 at a chance of 0.098469"]'::jsonb, 2, 'The engine refuses a normal whose low estimate, the mean less the standard normal 90th percentile times the standard deviation, is below 0: here -0.281552. It truncates no draw; a normal is taken for any class; and the line in the reasons is for a normal whose low estimate stays at or above 0 but which can still draw below 0.'),
  ('prms', 'advanced', 'module', 'm03-risked-quantities-and-classes', 11, 'A stated project W is a normal of mean 4.000000 and standard deviation 3.100000, whose low estimate is 0.027190. What does the engine do with its draws below 0?', '["It refuses the normal, since any chance below 0 is a refusal", "It keeps them in the total and prints a line with their chance, 0.098469, from lib/stats normalCDF", "It discards them and draws again until each draw is at or above 0, so the total can never fall below 0", "It keeps them but prints nothing, since the low estimate is above 0"]'::jsonb, 1, 'The low estimate is at or above 0, so the normal is accepted; it can still draw below 0, and the engine says so in its own words: W: a normal distribution draws below 0 with chance 0.098469 (lib/stats normalCDF); those draws stay in the total. No redraw or refusal follows, and the line is printed.'),
  ('prms', 'advanced', 'module', 'm03-risked-quantities-and-classes', 12, 'Why does the Ekene Upper sand normal (EKN-U, mean 4, standard deviation 0.8) carry no below-zero line in the engine''s reasons?', '["Its chance below 0 is exactly 0, since a normal of that mean cannot reach below 0", "The line is printed for Contingent Resources alone, and EKN-U is one of the three Reserves projects", "The line is printed only when a correlation is stated, and EKN-U''s stated pairs keep it apart from the others", "Its chance below 0 is 2.871050e-7, which prints as 0 at six decimals, so no line is added"]'::jsonb, 3, 'The engine returns a chance below 0 of 2.871050e-7 for EKN-U, which prints as 0 at six decimals, so it adds no line. A normal always has some chance below 0; the line depends on neither the class nor the correlation.'),
  ('prms', 'advanced', 'module', 'm03-risked-quantities-and-classes', 13, 'An aggregation input carries a lognormal with its mean and standard deviation and, beside it, three estimates. How does the engine answer?', '["a refusal: the estimates must be left out when the distribution is stated, since the engine reads them off it", "a result that uses the stated estimates and ignores the distribution", "a result that checks the two agree and prints the larger difference", "a refusal: the lognormal must be stated as a triangular-fit when estimates come with it"]'::jsonb, 0, 'The engine refuses both forms at once: projects[1].estimates must be left out when the distribution is stated (the engine reads the estimates off it). It chooses neither form for the caller and reconciles nothing; a triangular-fit takes estimates, and a lognormal takes a mean and a standard deviation.'),
  ('prms', 'advanced', 'module', 'm03-risked-quantities-and-classes', 14, 'The NUPRC release of 1 April 2026 prints the 2P associated gas at 100.21 and the 2P non-associated gas at 114.98 trillion cubic feet as at 1 January 2026. Each is stated to the engine as a constant at the above-field level. What does it return?', '["215.190000, reported as \"arithmetic-or-statistical\"", "a sampled P90 below 215.190000 on seed 1 and 100 draws, reported as the national 1P", "215.190000, reported as \"arithmetic\"", "a refusal, because published national figures have no low or high estimate"]'::jsonb, 2, 'The two constants add to 215.190000 (engine), matching the total the release prints, and above the field level the engine reports "arithmetic". Constants sample to the same figure on every draw; the release publishes only a 2P, which the call states as a constant; nothing is refused.'),
  ('prms', 'advanced', 'module', 'm03-risked-quantities-and-classes', 15, 'On that national gas call the engine''s labels read 1P, 2P and 3P, all at 215.190000. How are they read?', '["All three were published by the Commission and happen to be equal as at 1 January 2026, the date of the figures", "Only the 2P was published; each figure is stated as one value, so the three labels print it alike", "The 1P and the 3P are the engine''s own estimates of the national range around the one published figure", "The labels show the figure is risked at a chance of commerciality of 100, as a published total always is"]'::jsonb, 1, 'Each published 2P figure is stated as a constant, low, best and high the same, so the category labels read 1P, 2P and 3P for one stated figure, and only the 2P is what was published. The engine estimates no national range, and Reserves carry no chance of commerciality. A national figure is reported reserves with its date and who reported it.'),
  ('prms', 'advanced', 'module', 'm04-reconciliation', 1, 'The Ekene field Reserves (synthetic) open the year at 15.200000, 21.000000 and 27.500000 MMbbl. The movements are production 1.1, revisions 0.3, -0.2 and -0.6, transfers 3.4, 5.1 and 6.9, and improved recovery 0.5, 0.8 and 1.2. What computed closing 1P does the engine return?', '["18.300000", "15.200000, the opening, because a stated closing takes the place of the computed one", "25.600000", "33.900000, the closing of the high category"]'::jsonb, 0, 'Opening plus movements, category by category: 15.2 less 1.1, plus 0.3, 3.4 and 0.5 gives 18.300000 (engine). The stated closing is a check on the computed one and replaces nothing; 25.600000 and 33.900000 are the computed closings of 2P and 3P.'),
  ('prms', 'advanced', 'module', 'm04-reconciliation', 2, 'Carry the same Ekene movements through to the high category. Where does the 3P close?', '["27.500000", "25.600000", "33.900000", "38.387162"]'::jsonb, 2, '27.5 less 1.1, less 0.6, plus 6.9 and 1.2 gives 33.900000 (engine). The movements do not offset one another; 25.600000 is the 2P closing; and 38.387162 is an aggregation figure from a different call, a sum of three projects'' high estimates.'),
  ('prms', 'advanced', 'module', 'm04-reconciliation', 3, 'In a Reserves reconciliation, how does the engine apply a production movement?', '["From the 1P alone, since production draws on the proved volumes first", "As one quantity subtracted from the 1P, the 2P and the 3P alike", "In proportion to each category, so the 3P loses the most barrels", "From the 2P alone, with the 1P and the 3P moved by the revisions"]'::jsonb, 1, 'The engine''s basis reads that production comes out of every Reserves category alike: one quantity, 1.1 in the Ekene case, is subtracted from 1P, 2P and 3P. That is the engine''s stated convention, printed as a reading; no category is spared and nothing is prorated.'),
  ('prms', 'advanced', 'module', 'm04-reconciliation', 4, 'The Ekene production movement is typed as a low of 1 with a best and a high. What does the engine return?', '["a result that subtracts each stated figure from its own category", "movements[0].quantity must be left out for revisions (state low, best and high); got 1", "a result that averages the three figures and subtracts the average from every category", "movements[0].low must be left out for production (one quantity applies to every category); got 1"]'::jsonb, 3, 'Production is one quantity for every category, and the engine refuses it stated by category, in its own words. It neither subtracts per category nor averages; the "left out for revisions" message is the mirror case, a quantity stated on a movement that takes three figures.'),
  ('prms', 'advanced', 'module', 'm04-reconciliation', 5, 'A Contingent Resources reconciliation carries a production movement. What does the engine return?', '["a result that subtracts the production from 1C, 2C and 3C alike", "a result that moves the production into Reserves as a transfer", "a refusal: movements[0].low must be left out for production", "a refusal: produced quantities come out of Reserves, and sub-economic production is shown as a revision (PRMS 3.1.3.5)"]'::jsonb, 3, 'The engine refuses production in Contingent Resources and lists the six movement types it takes there; its message says produced quantities come out of Reserves and that sub-economic production moves from Contingent Resources to production and is shown as a revision (PRMS 3.1.3.5). It subtracts nothing and transfers nothing on its own.'),
  ('prms', 'advanced', 'module', 'm04-reconciliation', 6, 'How does the engine read the sign of a divestments movement?', '["It is entered positive and subtracted from every category", "It is signed, so a divestment is entered as a negative figure and added", "It is entered positive and added, like an acquisition", "It is entered as one quantity, like production"]'::jsonb, 0, 'Revisions and transfers are signed; improved recovery, extensions and discoveries and acquisitions are entered positive and added; divestments are entered positive and subtracted. The engine refuses a negative divestment; divestments take a low, a best and a high.'),
  ('prms', 'advanced', 'module', 'm04-reconciliation', 7, 'Suppose a divestment is typed as -1 at 1P to show barrels leaving. How does reconcile answer?', '["a result that adds the -1, since a negative divestment is an acquisition", "a result reading the sign as a slip", "movements[0].low must be a finite number at or above 0; got -1", "movements[0].type must be one of \"revisions\", \"transfers\"; got -1"]'::jsonb, 2, 'Divestments are entered positive and subtracted, so a negative figure is refused: movements[0].low must be a finite number at or above 0; got -1. The engine reinterprets no sign; the type message is about an unknown movement type and would name the type.'),
  ('prms', 'advanced', 'module', 'm04-reconciliation', 8, 'On the golden input rec-ekene-not-closing the 2P computed closing differs from the stated one by 0.200000 at a tolerance of 0.001000. What does the engine return?', '["a refusal naming the closing, since a reconciliation that misses is an error in the stated figures", "a result, closes false, with the line: the reconciliation does not close: 2P differs by 0.2 (tolerance 0.001)", "a result, closes true, since 0.2 rounds to 0 at the precision of the stated movements", "a result, closes false, with the stated closing replaced by the computed one"]'::jsonb, 1, 'A reconciliation that does not close is a result: the engine names each category that misses and by how much, in its own words. It refuses nothing, rounds nothing away and overwrites no stated figure; the stated closing stays as the check it is.'),
  ('prms', 'advanced', 'module', 'm04-reconciliation', 9, 'When the 2P miss is -0.250000 and the stated tolerance is exactly 0.250000 (rec-difference-exactly-tolerance), is the call closed?', '["closes false: the difference must be strictly inside the tolerance", "closes false: a negative difference never closes", "closes true: a difference equal to the tolerance closes", "a refusal: the tolerance must exceed every difference"]'::jsonb, 2, 'The engine''s reading is that a difference equal to the tolerance closes, printed as: the reconciliation closes: every category within the stated tolerance 0.25. The alternative it names, equal not closing, is a reading; the sign of the difference does not matter; and nothing is refused.'),
  ('prms', 'advanced', 'module', 'm04-reconciliation', 10, 'Suppose the 2P miss grows to -0.312500 while the stated tolerance stays 0.250000 (golden input rec-difference-above-tolerance). Does the call close?', '["closes false, since the miss of 0.312500 exceeds the tolerance in size", "closes true, because the difference is negative and so below the tolerance", "closes true, because the tolerance is read as a share of the 2P", "a refusal naming the tolerance, since the difference exceeds it"]'::jsonb, 0, 'The size of the difference, 0.312500, is above 0.250000, so the reconciliation does not close (engine, closes false). A negative difference is measured by its size; the tolerance is an absolute figure in the stated unit; and a miss is a result and no error.'),
  ('prms', 'advanced', 'module', 'm04-reconciliation', 11, 'The Ekene reconciliation carries 1.1 of production. What 2P replacement ratio does the engine return?', '["23.272727", "5.7", "0.300000", "5.181818"]'::jsonb, 3, 'The engine divides every movement other than production at 2P (revisions -0.2, transfers 5.1 and improved recovery 0.8, together 5.7) by the production 1.1: 5.181818. 23.272727 is the 2P life index, a different figure; 5.7 is the numerator before the division; 0.300000 is the 1P revision alone.'),
  ('prms', 'advanced', 'module', 'm04-reconciliation', 12, 'The engine''s 2P life index on the Ekene reconciliation is 23.272727 years. How is it read?', '["The closing 1P over the period''s production, read at the low estimate of the stated closing", "The closing 2P over the period''s production rate, read at the best estimate", "The opening 2P over the production, read before the movements", "The 2P replacement ratio multiplied by the period in years"]'::jsonb, 1, '25.600000 over 1.1 a year gives 23.272727 years (engine). The engine states that reading: the life index is read at the best estimate, and the alternative it names is the index at the low estimate. It uses the closing figure, and the replacement ratio is a separate line.'),
  ('prms', 'advanced', 'module', 'm04-reconciliation', 13, 'On the golden input rec-divest-acquire the divestments exceed the additions. What 2P replacement ratio does the engine return?', '["0.750000, reported by its size alone", "-0.750000, reported with its sign", "null, as for a period with no ratio", "a refusal, as a ratio cannot be negative"]'::jsonb, 1, 'Every movement other than production counts, divestments subtracted, so the ratio can fall below 0: -0.750000 (engine). The sign is kept, a figure is printed, and nothing is refused; the ratio is null only when the period carries no production.'),
  ('prms', 'advanced', 'module', 'm04-reconciliation', 14, 'The Ekene reconciliation prints its difference at 2P as 0.000000. Which statement is true of that difference?', '["It is not exactly 0; it is a floating-point residue of the sums, and the call closes because it lies within the tolerance 0.001000", "It is exactly 0, because the stated closing of 25.600000 was copied from the computed one", "It is exactly 0, so the tolerance plays no part in whether the reconciliation closes", "It is not exactly 0, so the reconciliation fails to close at the stated tolerance of 0.001000"]'::jsonb, 0, 'A figure that prints as 0.000000 at six decimals is not thereby 0: the engine''s difference is a floating-point residue of the sums, and the call closes because every difference is within the stated tolerance 0.001000 (engine, closes true). Printed alike is not equal; the residue is far smaller than the tolerance.'),
  ('prms', 'advanced', 'module', 'm04-reconciliation', 15, 'On rec-order-breaks the computed closing is 13.000000, 12.000000 and 14.000000. What does the engine report about its order?', '["a refusal, since every closing must be ordered low <= best <= high before the engine returns it", "a result that sorts the three categories into order before comparing them with the stated closing figures it was given", "a result with order breaks true and the line: the computed closing is out of order (1P <= 2P <= 3P fails)", "a result with order breaks false, since each category was built from the same stated movements"]'::jsonb, 2, 'An out-of-order computed closing is a result: the engine returns order breaks true and prints, in its own words, the computed closing is out of order (1P <= 2P <= 3P fails). The ordering refusal applies to a stated opening; the engine sorts nothing; and stated movements can leave the categories out of order however they were built.'),
  ('prms', 'advanced', 'module', 'm05-two-economic-limit-rules', 1, 'What does the canonical trailing trim of cashflow.ts, the economic limit every economics course in the academy uses, cut?', '["Every year whose net cash flow after tax is below 0, wherever it falls", "Every year after the cumulative net cash flow before tax and abandonment peaks", "Working back from the last year, every trailing year whose revenue less royalty less opex is below 0; a year with capital is kept, and so is a year at exactly 0", "Every trailing year whose revenue less royalty less opex is at or below 0, capital years included"]'::jsonb, 2, 'The trim works backward from the last year and stops at the first year that pays; it looks at revenue less royalty less opex, keeps a year with capital and keeps a year at exactly 0. It does not cut interior years or read tax; the cut after the cumulative peak is the PRMS rule; and a year at exactly 0 is kept.'),
  ('prms', 'advanced', 'module', 'm05-two-economic-limit-rules', 2, 'How does the PRMS rule of 3.1.3.1 to 3.1.3.4, as the engine checks it, place the economic limit?', '["At the last year whose own revenue less royalty less opex is at or above 0", "At the year the undiscounted cumulative net cash flow after tax and abandonment first turns positive and stays so", "At the licence expiry, whatever the cash flow, unless a renewal is stated", "At the year the cumulative net cash flow before income tax, allowances and abandonment reaches its maximum"]'::jsonb, 3, 'The PRMS rule places the limit at the peak of the cumulative net cash flow before income tax, allowances and abandonment; interim negative years count only when later positive years more than offset them. The last paying year is the canonical trim; a cumulative turning positive is no limit; and the licence cut is a separate step.'),
  ('prms', 'advanced', 'module', 'm05-two-economic-limit-rules', 3, 'The golden input econ-refuse-limit-disagrees states a low forecast of 100000, 10000, 25000 and 22000 barrels from 2027 to 2030 at 50 a barrel, with opex of 1000000 a year. What does the engine return?', '["a result at 2027, the more cautious of the two limits", "a refusal naming both years: the trailing trim gives 2030 and the cumulative peak gives 2027", "a result at 2030, the canonical limit, with the peak printed as a warning line", "a refusal saying the low forecast must be economic when the best case is, on the same prices and costs"]'::jsonb, 1, 'The last year pays, so the trim keeps every year to 2030; the cumulative peaks in 2027. The engine answers with neither and refuses, naming both years: they give 2030 and 2027. It picks no cautious or canonical answer for the caller; the "economic when the best case is" message belongs to a high case that fails.'),
  ('prms', 'advanced', 'module', 'm05-two-economic-limit-rules', 4, 'On that late-dip profile the canonical cash flow gives a cumulative before tax and abandonment of 4000000, 3500000, 3750000 and 3850000 from 2027 to 2030. Why does the PRMS rule stop in 2027?', '["The cumulative peaks in 2027: the later partial recovery to 3850000 never regains 4000000", "2028 is the first year whose revenue less royalty less opex is negative, so the PRMS rule stops before it", "2027 is the only year without opex", "The PRMS rule stops at the first year of production, whatever the later years of the forecast bring"]'::jsonb, 0, 'The PRMS limit is the year of the cumulative maximum, 4000000 in 2027; the 2029 and 2030 years add back 250000 and 100000 and leave the cumulative at 3850000, below the peak, so the interim loss of 2028 is not offset. A negative single year is what the trim reads; every year carries opex; and no rule stops at the first year by definition.'),
  ('prms', 'advanced', 'module', 'm05-two-economic-limit-rules', 5, 'On the same profile, why does the canonical trailing trim keep every year to 2030?', '["The last year carries capital, and the canonical trim keeps every year with capital in it", "The last year pays: its revenue less royalty less opex is 100000.000000, above 0", "The trim reads the cumulative before tax, which stays positive in every year of the profile", "The trim keeps every year inside the licence, and 2030 falls before any stated expiry"]'::jsonb, 1, 'In 2030 revenue of 1100000.000000 less opex of 1000000.000000 leaves 100000.000000 (derived from the canonical cash flow), so working back from the end the trim finds a paying year at once and cuts nothing. The profile states no capital; the trim reads each year''s own margin, and the cumulative plays no part in it; the licence cut is a separate step.'),
  ('prms', 'advanced', 'module', 'm05-two-economic-limit-rules', 6, 'Why does the engine refuse where the two rules disagree?', '["The canonical rule is wrong on late-dip profiles, and the PRMS rule is not yet built into the engine", "A disagreement means the forecast holds a typing error", "Either answer would move a Reserves figure by a choice the caller did not make, so both years are named for the caller to see", "The two rules can never disagree on a real field, so a disagreement marks a synthetic case"]'::jsonb, 2, 'The canonical rule would count the late barrels and the PRMS rule would drop them; answering with either would move a Reserves figure by a choice the caller never made, so the engine refuses and names both years. Neither rule is called wrong; the engine computes both to compare them; and the profile is a legitimate forecast with no typing error in it.'),
  ('prms', 'advanced', 'module', 'm05-two-economic-limit-rules', 7, 'Why does the engine not simply switch the canonical cash flow over to the PRMS rule?', '["It would move every figure the academy''s other economics courses and the Suite''s economics app teach from cashflow.ts", "The PRMS rule cannot be computed from a yearly cash flow", "The PRMS rule applies only to Contingent Resources", "SPE-PRMS 2018 forbids a cumulative peak for Reserves"]'::jsonb, 0, 'The canonical cash flow is shared; changing it would move figures across the academy and the Suite, so that change is a separate decision for the platform, and the engine keeps both rules visible by refusing where they part. The peak is computed from the yearly cash flow; the rule is about Reserves; and PRMS 3.1.3.1 is the rule itself.'),
  ('prms', 'advanced', 'module', 'm05-two-economic-limit-rules', 8, 'After the refusal on a late-dip profile, what can the caller do?', '["Remove the opex from the dip years so the trim cuts them", "Set the licence expiry to 2027, which makes both rules give the same year by construction", "Ask the engine for the PRMS limit with a stated option that switches rules", "State a forecast on which the two rules agree, or split the project at the dip"]'::jsonb, 3, 'The engine''s own advice is to state a forecast on which the two agree, the technical forecast ending where the project stops paying, or to split the project at the dip; the refusal names both years so the barrels in question can be seen. Altering stated costs or the licence to force agreement changes the facts, and the engine offers no rule-switching option.'),
  ('prms', 'advanced', 'module', 'm05-two-economic-limit-rules', 9, 'On the Ekene Main waterflood (EKN-1, golden input econ-ekene), a declining forecast with no late capital, where does the best case reach its economic limit under the canonical rule?', '["2040, the licence expiry, where the high case stops", "2041, the last year of the technical forecast", "2033, with 7 trailing years cut from the end", "2037, with 3 trailing years cut"]'::jsonb, 3, 'On a declining forecast with no late capital the two rules agree, and the engine uses the canonical one and checks it against the peak: the best case stops in 2037 with 3 trailing years cut (engine). 2040 is the licence cut and the high case''s limit; 2041 is the end of the technical forecast; 2033 is the low case''s limit.'),
  ('prms', 'advanced', 'module', 'm05-two-economic-limit-rules', 10, 'Two golden inputs differ by one barrel in the last year: 20000 and 19999 barrels at 50 a barrel against opex of 1000000. What economic limits does the engine return?', '["2028 for both, since a trailing year at exactly 0 does not pay and the trim cuts it with the negative one", "2029 for both, since one barrel in the last year is inside any tolerance the canonical trim applies", "2029 for 20000 barrels, where the last year is exactly 0 and kept; 2028 for 19999, where it is cut", "2029 for 19999 and 2028 for 20000"]'::jsonb, 2, '20000 barrels at 50 is 1000000, exactly the opex, and the canonical trim keeps a year at exactly 0: limit 2029, 0 years cut, 2P oil 170000.000000. One barrel less makes the last year negative: limit 2028, 1 year cut, 2P oil 150000.000000 (engine). The trim has no tolerance; the boundary is inclusive at 0.'),
  ('prms', 'advanced', 'module', 'm05-two-economic-limit-rules', 11, 'The golden input econ-exactly-zero-not-economic gives a best case whose undiscounted net cash flow is exactly 0.000000. What does the engine return?', '["not economic, and the project stays in Contingent Resources, economically not viable", "economic, since a trailing year at exactly 0 is kept by the canonical trim and the test follows the trim", "a refusal, because a case at exactly 0 cannot be classed", "economic, with 1P set to 0 and the 2P and 3P kept, as when a low case fails the test"]'::jsonb, 0, 'The engine reads the economic test as an undiscounted net cash flow above 0, so exactly 0 is not economic: not commercial, the best case fails (PRMS 2.1.2.2, 3.1.2.1), economically not viable. That boundary is strict, where the trim''s is inclusive; a result is returned; and 1P set to 0 applies when the low case fails and the best passes.'),
  ('prms', 'advanced', 'module', 'm05-two-economic-limit-rules', 12, 'Otherwise commercial projects state that development starts within 5 and within 6 years, with a longer time-frame not stated as justified. What classes does the engine return?', '["Contingent Resources at both, since 5 years exactly is not within the benchmark", "Reserves at 5 years, the benchmark met; Contingent Resources at 6", "Reserves at both, since the benchmark is a recommendation", "Reserves at 6 and Contingent Resources at 5"]'::jsonb, 1, 'The engine reads the five-year benchmark as met at five years (its stated reading; the alternative it names is five years exactly not met): 5 years gives Reserves and 6 years gives Contingent Resources with the time-frame not met. A benchmark the engine applies moves the class, and the later start is the one that fails.'),
  ('prms', 'advanced', 'module', 'm05-two-economic-limit-rules', 13, 'Under PIA 2021 s.78(9), the Nigerian notes are run at 10 and at 11 years since a significant discovery was declared. What does the engine print?', '["At 10 years the retention has ended, since the period is less than 10 years", "At 11 years the class moves to Discovered Unrecoverable", "At both, the area is inside retention, since the Commission may extend the period without limit under the Regulations", "At 10 years the retention period is running; at 11 it has ended, so the area is relinquished unless a commercial discovery was declared (s.78(13))"]'::jsonb, 3, 'The retention runs at most 10 years from the declaration, so 10 is inside and 11 has ended; the engine prints the s.78(13) consequence as a note. The notes do not change the PRMS class, which stays Contingent Resources at both; and reg. 6(3) lets the Commission grant up to the maximum the Act allows, no further.'),
  ('prms', 'advanced', 'module', 'm05-two-economic-limit-rules', 14, 'The engine''s economic test on a case includes the abandonment cost. How is that choice taught?', '["As a reading the engine states, with the alternative it names: the test made before the abandonment cost", "As the rule of PRMS 3.1.2.1 itself, which the engine applies as binding without naming any alternative at all", "As a stated input a panel may switch off without saying so, leaving the test to the learner''s own choice", "As a figure the course grades under both choices"]'::jsonb, 0, 'The engine''s basis cites 3.1.2.1 with ADR included, and the course teaches it as a stated reading beside the alternative, the test before the abandonment cost as the producibility determination is made. No stated reading is taught as the law; no input is supplied silently; and no graded figure moves under any reading.'),
  ('prms', 'advanced', 'module', 'm05-two-economic-limit-rules', 15, 'On EKN-1 the licence expires in 2040 with no renewal expected. What happens to the high case''s barrels in the expiry year and after it?', '["The expiry year is cut along with every later year, since the licence ends as that year begins", "The later years are kept and reported in the 3P, since the high case is the one that reaches them", "The expiry year 2040 is kept; the later years are reported as beyond the licence", "The later years are kept and moved into Contingent Resources by the engine, with their class printed"]'::jsonb, 2, 'The licence boundary keeps the expiry year, and the years after it are cut before the cash flow is run, their barrels reported as beyond the licence: 601257.000000 barrels of oil on the high case (engine). The engine classifies none of them; SPE-PRMS 2018 3.3.3.2 (cited in FAQ answer 4.4) keeps such quantities outside Reserves unless an extension is reasonably expected.'),
  ('prms', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 1, 'A learner wants the engine to build the Ekene low, best and high production forecasts from well rates. Where does that work belong?', '["In the engine''s economicLimit, which fits a decline to the stated rates before it runs the cash flow", "In the dca course; the engine takes three stated technical forecasts, year by year", "In the cashflow course, which builds forecasts before discounting them", "Nowhere: forecasts are always a stated input"]'::jsonb, 1, 'The engine builds no production forecast; a forecast from rates by decline or type curves belongs to the dca course (Decline Curve Analysis), and the engine takes three stated technical forecasts. economicLimit fits nothing; the cashflow course owns the ledger and discounting; and the dca course does own forecasting from rates.'),
  ('prms', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 2, 'A reserves report needs recoverable volumes from maps and rock properties. What does the engine take in their place?', '["Stated estimates or distributions; the volumetrics belong to the reservoircalc course", "A material balance run inside aggregate, fitted to the stated opening of the reconciliation", "The fitted triangular of lib/stats, which it builds from the maps", "The mbal course''s figures, imported at run time"]'::jsonb, 0, 'Volumetrics from maps and rock properties belong to reservoircalc (Reservoir Volumetrics) and material balance to mbal (Material Balance); the engine takes stated estimates or distributions. It runs no material balance; lib/stats fits a triangular through stated estimates and reads no map; and it imports nothing from another course.'),
  ('prms', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 3, 'Which Nigerian fiscal figures does the engine compute for its economic limit?', '["The PIA 2021 royalty by terrain and price, read from the gazette", "The hydrocarbon tax and companies income tax of the PIA 2021, applied through cashflow.ts", "None: it takes a stated royalty rate and form and a stated tax rate, and the pia course teaches the fiscal terms", "The Ekene royalty of 15.000000 percent, which is the onshore rate of the Act"]'::jsonb, 2, 'The engine computes no fiscal regime beyond a stated royalty and tax; royalty rates by terrain and price, hydrocarbon tax and companies income tax belong to the pia course. The Ekene 15.000000 percent royalty is a synthetic teaching figure, and the fixture says it is not a rate of the Petroleum Industry Act 2021.'),
  ('prms', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 4, 'Which course of the academy owns the price deck behind a reserves estimate?', '["The pia course, since the Commission publishes the prices for royalty", "The cashflow course, which sets the academy''s price forecast for every economics course", "The uncertainty course, which samples prices on a seed", "None: prices are always a stated input, year by year"]'::jsonb, 3, 'The engine sets no price deck, and no course owns one: prices are a stated input. The pia course teaches fiscal terms, the cashflow course the ledger and discounting, and the uncertainty course distributions and Monte Carlo as a subject; none of them supplies a price forecast to this engine.'),
  ('prms', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 5, 'What Nigerian booking or reporting rule does the engine apply to a reserves figure?', '["None: no gazetted NUPRC reserves reporting regulation or booking guideline was found on the list read 2026-09-27", "The NUPRC booking guideline of 2026", "The Commercial Regulations 2025, reg. 6, which sets how reserves are booked", "The PIA 2021 s.7(i), which fixes the categories a licensee reports"]'::jsonb, 0, 'No gazetted Nigerian booking or reporting rule was found, so the course teaches the PRMS classes and states none. Regulation 6 of the Commercial Regulations 2025 asks for a status report that includes the reserves situation, taught by concept; s.7(i) gives the Commission the evaluation of national reserves and fixes no categories.'),
  ('prms', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 6, 'Fifty-one projects go into one aggregate call. Which message comes back?', '["a result on the first 50 projects, the 51st dropped", "iterations must be at most 45454 for 11 projects (iterations x projects at most 500000); got 51", "a result, since the cap binds only above the field level", "projects must have at most 50 entries; got 51"]'::jsonb, 3, 'DEFAULTS.MAX_PROJECTS is 50, and a call over it is refused in the engine''s own words. Nothing is truncated; the draw-work message is a separate cap on draws times projects; and every cap applies at every level.'),
  ('prms', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 7, 'An aggregation of 11 projects asks for 200000 draws. What does the engine return?', '["a result on 200000 draws, since 200000 is the MAX_ITERATIONS cap and a call exactly at the cap is always allowed", "a refusal: iterations must be at most 45454 for 11 projects (iterations x projects at most 500000)", "a result on 45454 draws, the most the stated projects allow, with a warning line in the reasons saying so", "iterations must be an integer from 100 to 200000; got 200000"]'::jsonb, 1, 'Draws times projects may not exceed 500000, because the correlated draw grows with the square of the project count; the refusal names the most draws 11 projects allow, 45454. 200000 is within MAX_ITERATIONS alone but not with 11 projects; the engine reduces nothing silently; and the range message fires only outside 100 to 200000.'),
  ('prms', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 8, 'An aggregation states its correlation with a key named matrix. What does the engine return?', '["a result that reads the matrix and checks it is positive semidefinite", "a result that ignores the unknown key and uses the stated rho", "correlation.matrix is not an accepted key; the accepted keys of correlation are type, rho, pairs", "correlation must be an object { type: \"uniform\", rho } or { type: \"pairs\", pairs } (stated; no default); got nothing"]'::jsonb, 2, 'Every function refuses an input key it does not read, at every level, naming the key, its path and the accepted keys. A misspelt or unknown key is refused by name, neither dropped nor guessed at; the object-shape message is for a correlation left out entirely.'),
  ('prms', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 9, 'On econ-ekene a stated probe removes the reporting basis and adds a top-level key named basis. Which refusal comes back?', '["The unknown key basis, listing the accepted top-level keys, because accepted keys are checked before any input is read", "The missing reportingBasis, since a required input outranks an unknown one", "Both refusals together, one per line, in the order the keys were typed", "Neither: the engine reads basis as a spelling of reportingBasis"]'::jsonb, 0, 'Every function checks its accepted keys before it reads an input, so the engine''s message is: basis is not an accepted key; the accepted keys at the top level are effectiveYear, forecasts, prices, costs, royalty, tax, workingInterestPct, licence, reportingBasis, discountRatePct, mscfPerBoe. It returns one refusal, and it matches no spelling.'),
  ('prms', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 10, 'The 2011 Guidelines print the arithmetic Proved of blocks A and B as 71.8 in Table 6.2 and as 72 on Fig. 6.5. What does the course make of the pair?', '["The table is a misprint and the figure of 72 is the Guidelines'' value, which the engine reproduces", "The figure rounds the table; the engine returns 71.800000", "The two describe different blocks of the Guidelines'' example", "The figure prints the probabilistic Proved of the two blocks"]'::jsonb, 1, 'Fig. 6.5 rounds Table 6.2''s 71.8 to 72, and the engine''s arithmetic sum is 71.800000. Neither is a misprint, both describe blocks A and B, and the probabilistic Proved of independent blocks is a separate figure the Guidelines print as 77.'),
  ('prms', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 11, 'Which edition of the Guidelines for Application of the PRMS does the course cite, and why?', '["The 2022 edition, which supersedes 2011 and is free to download from SPE", "The 2018 edition published with SPE-PRMS 2018", "The 2011 edition: the 2022 revision is sold and was not read", "The 2011 edition, because the 2022 revision withdrew the aggregation chapter altogether"]'::jsonb, 2, 'The Guidelines were revised in 2022; that edition is sold and was not read, so the course names the 2011 edition by its year and uses its numbers and section numbers only. There is no 2018 edition of the Guidelines, and nothing read says the 2022 revision withdrew a chapter.'),
  ('prms', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 12, 'The NUPRC release of 1 April 2026, as its page renders, prints the 2P crude oil figure as 09 billion barrels. What does the course do with it?', '["Reads it as 9 billion barrels", "Completes it from the digits of the condensate figure", "Derives the crude oil figure as the total 37.01 less the condensate 5.92, reported as the release''s own figure", "Uses only the gas figures and the total, and computes nothing from the truncated oil figure"]'::jsonb, 3, 'The crude oil figure is truncated on the page, so the course uses only the gas figures and the total and computes nothing from the truncated one. Reading it as 9, or completing it by any arithmetic, puts a figure in the release''s mouth that the page does not print.'),
  ('prms', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 13, 'The consolidated PRMS errata (May 2022, item 5) revise the glossary entry for "economic". What follows for the engine''s economic test?', '["The test is made at the stated discount rate of 10.000000 percent on the Ekene case", "The test is undiscounted, matching PRMS 3.1.2.1, and the engine applies it undiscounted", "The test is made on the NPV at the working interest", "The errata leave the test to the caller''s choice of discount rate, so the engine takes none"]'::jsonb, 1, 'Item 5 makes the glossary entry read a zero percent discount rate, matching 3.1.2.1: the economic test is undiscounted, which is the test the engine applies. The stated discount rate sets the NPV the engine reports and does not enter the test.'),
  ('prms', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 14, 'Which of these does prms.js carry code for of its own?', '["A cash flow and NPV calculation written for reserves work", "A seeded sampler and quantile reader alongside lib/stats", "A percentile convention that reads P90 as the 0.9 quantile", "The classification, category, economic-limit, aggregation and reconciliation logic, with its imports doing the cash flow, sampling and percentile work"]'::jsonb, 3, 'The engine imports computeCashFlow and applyJV from cashflow.ts, the canonical seeded Monte Carlo from lib/stats and the P90, P50 and P10 labels from lib/conventions/percentile.js, and carries no cash flow, NPV, discounting, sampler or percentile code of its own. It reads P90 as the 0.1 quantile of the totals.'),
  ('prms', 'advanced', 'module', 'm06-what-the-engine-does-not-compute', 15, 'The engine''s category labels on an economic limit and on an aggregation are outcome labels only. What do they not say?', '["That the low case carries the P90 label and the high case the P10 label, as the convention sets", "That 1P, 2P and 3P name the low, best and high estimates of the Reserves in the stated unit", "That a stated deterministic scenario has a 90 percent chance of being met or exceeded", "That P90 marks the low estimate, per lib/conventions/percentile.js"]'::jsonb, 2, 'The engine says its labels are outcome labels only: it does not say a stated deterministic scenario has a 90 percent chance. The other three are what the labels do say: P90 on the low case and P10 on the high, 1P, 2P and 3P for the Reserves categories, and the low estimate as P90 per the canonical convention.'),
  ('prms', 'advanced', 'final', null, 1, 'Summing the best estimates of EKN-1, EKN-2 and EKN-U, which 2P does arithmetic aggregation report in MMbbl?', '["26.821102", "26.430497", "16.650000", "26.396958"]'::jsonb, 3, 'The arithmetic 2P adds the three best estimates, 16.650000, 5.746958 and 4.000000: 26.396958 (engine). The sum of the means, 26.821102, is printed beside it and is no category; 26.430497 is a sampled figure; 16.650000 is one project.'),
  ('prms', 'advanced', 'final', null, 2, 'For the Ekene Upper sand, a normal centred on 4.000000 with spread 0.800000, which figure enters the 1P sum?', '["4.000000", "3.945035", "2.974759", "5.025241"]'::jsonb, 2, 'The low estimate of a normal is its mean less the standard normal 90th percentile times its standard deviation: 2.974759 (engine). 4.000000 is the mean and best estimate; 3.945035 is EKN-2''s low estimate, read off its lognormal; 5.025241 is the high estimate, exceeded with only 10 percent probability.'),
  ('prms', 'advanced', 'final', null, 3, 'Which sources does the engine''s basis line cite for an aggregation?', '["SPE-PRMS 2018 3.1.2.1 and 3.1.2.8, with the FAQ answers 3.3 and 3.4", "SPE-PRMS 2018 4.2.5 and 4.2.6, 17 CFR 229.1202(a)(3), and the 2011 Guidelines 6.3", "The 2022 Guidelines for Application of the PRMS alone, since they supersede every earlier text", "17 CFR 210.4-10(a)(24) alone, which sets the 90 percent probability for every total"]'::jsonb, 1, 'The aggregation basis cites SPE-PRMS 2018 4.2.5 and 4.2.6, 17 CFR 229.1202(a)(3) (Regulation S-K Item 1202) and the Guidelines for Application of the PRMS (November 2011) 6.3. 3.1.2.1, 3.1.2.8 and the FAQ answers belong to the economic test; the 2022 Guidelines were not read; 210.4-10(a)(24) is the SEC''s probability wording for proved reserves.'),
  ('prms', 'advanced', 'final', null, 4, 'Blocks A and B of the 2011 Guidelines'' Table 6.2 are added arithmetically by the engine. What are the low, best and high of the sum?', '["76.654150, 89.000000 and a sampled high", "71.800000 for the low, the rest left to the sampler", "71.800000, 89.000000 and 106.200000, each an exact sum", "72 for the low as Fig. 6.5 rounds it, the rest rounded alike"]'::jsonb, 2, 'The engine adds lows, bests and highs: 71.800000, 89.000000 and 106.200000 (engine), and the Guidelines print 71.8 in Table 6.2. 76.654150 is the exact low of an independent sum, a different method; the arithmetic call sets every category itself; and 72 is the figure''s rounding of the table, which the engine does not round.'),
  ('prms', 'advanced', 'final', null, 5, 'The first line of the engine''s reasons on the Ekene Reserves call names the class, the project count and the level. What else does it state?', '["that the three projects are independent unless the caller states a matrix", "that correlation is stated for 3 pairs, citing PRMS 4.2.5.3", "the seed and the draw count, citing lib/stats as the source of both of them", "that the call is at the above-field level, so only arithmetic sums will follow"]'::jsonb, 1, 'The engine''s opening line reads: Reserves, 3 projects at the field, property or project level; correlation stated for 3 pairs (PRMS 4.2.5.3). Nothing is assumed independent, since correlation is always stated; the seed and draws appear in the statistical line; and this call is at the field level.'),
  ('prms', 'advanced', 'final', null, 6, 'Set the arithmetic 3P of 38.387162 beside the sampled P10 of the Ekene total on the stated pairs (seed 20271112, 20000 draws). Which is larger?', '["The sampled P10, since sampling widens the high end of a total", "Neither: the two agree once the pairs are stated for every project", "The arithmetic 3P, by the gap the engine''s fourth reason prints", "They cannot be set side by side, since one is a sum and the other a quantile of a different class"]'::jsonb, 2, 'On that seed and those draws the sampled P10 of the total is 36.465253, and the engine''s reason line reports the arithmetic high above the statistical high by 1.921909. Adding every project''s high assumes they all come in high together, which overstates the top of the range; pair correlations of 0.5 and 0.2 fall short of total dependence, and both figures are Reserves in MMbbl.'),
  ('prms', 'advanced', 'final', null, 7, 'Why does EKN-1''s mean of 16.821102 differ from its best estimate of 16.650000?', '["Its fitted triangular is skewed, so its mean and its best estimate part", "The engine adds a risk margin to the mean of every Reserves project it aggregates", "The best estimate is rounded to two decimals and the mean is not", "The mean is the sampled mean of the total on seed 20271112"]'::jsonb, 0, 'The triangular fitted through 8.890000, 16.650000 and 24.990000 runs from 2.628420 to 31.737202 with its mode at 16.097684; a skewed distribution has a mean apart from its median, and the engine reads 16.821102 off it in closed form. No margin is added, the estimates are stated figures, and the project mean is closed-form.'),
  ('prms', 'advanced', 'final', null, 8, 'For the Guidelines'' independent blocks the sampled P90 on seed 2011 and 200000 draws is 76.623299, against the exact low 76.654150. What is the 0.030852 between them?', '["A defect in lib/stats, since a correct sampler returns the exact low", "The gap between a normal reading and a lognormal reading of the blocks", "A rounding difference, since the Guidelines print 77 for the figure", "Sampling error at those draws: the seeded Monte Carlo estimates a figure the closed form gives exactly"]'::jsonb, 3, 'The exact low of two independent normals is 76.654150 (derived); the sampled P90 differs from it by 0.030852 at these 200000 draws, the sampling error every Monte Carlo carries. It is no defect; the lognormal reading gives a different sampled figure, 76.434906; and the Guidelines'' 77 is a rounding of either.'),
  ('prms', 'advanced', 'final', null, 9, 'The pair EKN-2 and EKN-1 turns up twice in a pairs correlation, once in each order. Which message does the engine give?', '["correlation.pairs[3] must be a pair stated once; got {\"a\":\"EKN-2\",\"b\":\"EKN-1\",\"rho\":0.5}", "a result that keeps the later of the two statements of the pair", "a result that averages the two statements of the pair", "correlation.pairs must be one pair for each of the 3 pairs of varying projects; got \"4 pairs\""]'::jsonb, 0, 'A pair may be stated once, in either order, and the engine refuses the repeat by its index in the engine''s own words. It keeps neither statement for the caller and averages nothing; the "one pair for each" message is for a pair left out.'),
  ('prms', 'advanced', 'final', null, 10, 'A pairs correlation names EKN-C, the constant project, as the second member of a pair. What does the engine return?', '["a result, since a correlation stated on a constant has no effect on any of the draws", "correlation.pairs[3].b must be one of \"EKN-1\", \"EKN-2\", \"EKN-U\"; got \"EKN-C\"", "a refusal saying a constant must be given a correlation of 0", "a result with EKN-C left out of the total"]'::jsonb, 1, 'Correlations are stated between varying projects, and a constant is not one: the engine refuses the pair and lists the three varying ids. It does not accept and ignore the pair, it asks for no special value, and a constant stays in every total, adding its value to every draw.'),
  ('prms', 'advanced', 'final', null, 11, 'Fifty Monte Carlo draws are requested for a total. How does the engine respond?', '["a result on 100 draws, the smallest the engine accepts", "iterations must be an integer from 100 to 200000; got 50", "a result on 50 draws, with a warning about sampling error", "iterations must be at most 45454 for 11 projects (iterations x projects at most 500000); got 50"]'::jsonb, 1, 'The draw count is a stated input from 100 to 200000, and 50 is refused in the engine''s own words. It raises no count on its own and returns no result on too few draws; the draw-work message caps draws times projects from above.'),
  ('prms', 'advanced', 'final', null, 12, 'The correlation block is missing from a call to aggregate. What comes back?', '["a result on independent projects, the usual assumption", "a result on total dependence, which matches the arithmetic sums", "correlation must be an object { type: \"uniform\", rho } or { type: \"pairs\", pairs } (stated; no default); got nothing", "correlation.rho must be a number above -1 and below 1 (the canonical sampler takes a correlation strictly between -1 and 1); got nothing"]'::jsonb, 2, 'Correlation is always stated, and a call without it is refused, naming the two shapes it accepts. The engine assumes neither independence nor total dependence; the rho message is for a uniform correlation whose rho is out of range.'),
  ('prms', 'advanced', 'final', null, 13, 'A "triangular-fit" project gives three estimates. Which lib/stats function named in the engine''s Monte Carlo basis turns them into a distribution?', '["fitTriangularToPercentiles", "createCorrelatedSampler, which fits each marginal as it draws", "mulberry32, the seeded generator", "quantile"]'::jsonb, 0, 'The Monte Carlo basis names lib/stats/stats.js: createCorrelatedSampler (Gaussian copula, Cholesky), mulberry32, fitTriangularToPercentiles and quantile. The fit is fitTriangularToPercentiles; the sampler correlates the draws and fits nothing; mulberry32 generates the seeded numbers; quantile reads the P90, P50 and P10 off the totals.'),
  ('prms', 'advanced', 'final', null, 14, 'For the Guidelines'' independent blocks, what exact mean of the total does the engine print beside the sampled mean of 89.020435 (seed 2011, 200000 draws)?', '["89.020435, since the sampled mean is the exact one at 200000 draws", "76.654150, the exact low of the independent sum", "89.000000, the sum of the two expectations", "71.800000"]'::jsonb, 2, 'The mean of a total is the sum of the means: 53.400000 and 35.600000 give 89.000000 (engine), printed as exact; the sampled 89.020435 differs by sampling error. 76.654150 is the exact low of the sum; 71.800000 is the arithmetic sum of the lows.'),
  ('prms', 'advanced', 'final', null, 15, 'Which chance does the engine use for each Ekene Contingent project when it computes the risked mean?', '["Its chance of commerciality, which for a discovered project is the chance of development", "Its chance of geologic discovery, which for a discovered project is 100", "The product of the chance of geologic discovery and of development, as for a prospect or a lead", "The average of the three projects'' chances, applied to the sum of the means"]'::jsonb, 0, 'For a discovered project Pc = Pd (PRMS 2.1.3.3), and the risked mean takes each project''s stated chance of commerciality times its mean. A chance of geologic discovery is refused for a discovered accumulation; Pg x Pd is the Prospective case; and no average chance is used.'),
  ('prms', 'advanced', 'final', null, 16, 'Which low estimate comes off the triangular stated for Ekene West tight sand (EKN-5)?', '["2.837722", "3.000000", "4.585786", "1.707107"]'::jsonb, 3, 'The engine reads a stated triangular''s low, best and high in closed form: 1.707107, 2.837722 and 4.585786 MMboe, with a mean of 3.000000 (engine). The best and the mean are different figures, and 4.585786 is the high estimate, met or exceeded with only 10 percent probability.'),
  ('prms', 'advanced', 'final', null, 17, 'A stated triangular gives min 3, mode 2 and max 6. What does the engine return?', '["a triangular with the min and mode swapped into order", "a result read as a triangular-fit through 3, 2 and 6", "a refusal saying the fitted triangular would reach below 0", "projects[2].distribution must be a triangular with min <= mode <= max and min < max; got {\"type\":\"triangular\",\"min\":3,\"mode\":2,\"max\":6}"]'::jsonb, 3, 'A stated triangular must run min <= mode <= max with min < max, and the engine refuses one out of order in its own words. It reorders nothing, fits nothing it was not asked to fit, and the below-zero refusal belongs to a fit through estimates.'),
  ('prms', 'advanced', 'final', null, 18, 'EKN-4 in the Ekene Contingent Resources is a triangular fitted through stated low, best and high of 3.000000, 4.500000 and 6.500000. What mean does the engine read off it?', '["4.500000", "4.637674", "6.500000", "13.000000"]'::jsonb, 1, 'The engine reads the mean of the fitted triangular in closed form: 4.637674 MMboe (engine), above its best estimate of 4.500000 because the triangular is skewed. 6.500000 is its high estimate; 13.000000 is EKN-3''s mean.'),
  ('prms', 'advanced', 'final', null, 19, 'A report quotes the Ekene Contingent figure 20.637674 MMboe. How must it be described?', '["As the risked mean of the Ekene Contingent Resources", "As the arithmetic 2C of the three Contingent projects", "As the unrisked sum of the means of EKN-3, EKN-4 and EKN-5, with no chance of commerciality applied", "As the Ekene Reserves and Contingent Resources together"]'::jsonb, 2, '20.637674 is the sum of means with no chance applied; the risked mean on the stated chances is 10.114488 (engine). A sum of means is no category, and the classes are never added into one figure; "risked" always names its chance, so the unrisked figure says it is unrisked.'),
  ('prms', 'advanced', 'final', null, 20, 'On what correlation, seed and draws are the Ekene Contingent Resources sampled?', '["The Reserves pair correlations, seed 20271112 and 20000 draws, reused from that call", "A uniform correlation of 0.300000, seed 20271113 and 20000 draws, all stated", "No correlation, since risked projects are sampled independently", "A correlation fitted from the three chances of commerciality"]'::jsonb, 1, 'The fixture states a uniform correlation of 0.300000 with seed 20271113 and 20000 draws for the Contingent call. Every call states its own correlation, seed and draws; nothing is reused from another call, assumed or fitted from the chances.'),
  ('prms', 'advanced', 'final', null, 21, 'Why does the engine return only an arithmetic figure as reportable on the national gas total of 215.190000?', '["The call is made at the above-field level, where the engine reports the arithmetic sums", "The figures are constants, and constants cannot be sampled", "The Commission forbids statistical totals in its release", "Gas figures are always added arithmetically, whatever the level"]'::jsonb, 0, 'The golden input states the two published figures at the above-field level, and above the field the engine reports "arithmetic". Constants can be sampled and simply return their value on every draw; the release is cited for its figures and sets no method; and the level, whatever the fluid, decides what may be reported.'),
  ('prms', 'advanced', 'final', null, 22, 'After one year of movements, what best-estimate closing does reconcile compute for the Ekene field?', '["21.000000", "26.396958", "33.900000", "25.600000"]'::jsonb, 3, '21 less 1.1, less 0.2, plus 5.1 and 0.8 gives 25.600000 (engine). 21.000000 is the opening; 26.396958 is an aggregation figure from another call; and 33.900000 is the computed closing 3P.'),
  ('prms', 'advanced', 'final', null, 23, 'The Ekene transfers movement is +3.4, +5.1 and +6.9. What does the fixture''s note say it records?', '["Ekene infill wells moved from Contingent Resources at the investment decision", "Ekene Main production for 2027", "A waterflood performance review of the Ekene Main project and its injection wells", "A water injection pattern change that added recovery"]'::jsonb, 0, 'Transfers between classes are signed, positive in and negative out, and the Ekene note records the infill wells moving in from Contingent Resources at the investment decision. Production, the waterflood performance review and the injection pattern change are the other three movements, a production, a revision and improved recovery.'),
  ('prms', 'advanced', 'final', null, 24, 'Someone types a single quantity of 1 on a revisions row, the shape production takes. Which refusal follows?', '["a result applying the quantity to every category, as for production", "a result applying the quantity to the 2P alone", "movements[0].low must be left out for production (one quantity applies to every category); got 1", "movements[0].quantity must be left out for revisions (state low, best and high); got 1"]'::jsonb, 3, 'Revisions take a low, a best and a high; one quantity is the shape of production alone. The engine refuses the quantity in its own words and spreads it nowhere; the other message is the mirror refusal for production stated by category.'),
  ('prms', 'advanced', 'final', null, 25, 'A caller asks reconcile to roll Prospective Resources forward a year. What comes back?', '["a result with the movements applied to 1U, 2U and 3U", "resourceClass must be one of \"reserves\", \"contingent\"; got \"prospective\"", "a result, provided no production movement is stated", "a refusal naming the movement types for Contingent Resources"]'::jsonb, 1, 'Reconcile takes Reserves and Contingent Resources only, and it refuses the Prospective class by name in its own words. It returns no 1U, 2U or 3U roll-forward, whatever the movements, and the message listing the Contingent movement types is the one for production stated in Contingent Resources.'),
  ('prms', 'advanced', 'final', null, 26, 'An opening of 21 at 1P, 15.2 at 2P and 27.5 at 3P is typed into reconcile. What happens?', '["a result that sorts the opening into order before the movements are added", "a refusal: opening.best must be at least the low; got 15.2", "a refusal: opening must be ordered low <= best <= high", "the low and the best swapped, with a line in the reasons"]'::jsonb, 2, 'An opening out of order is refused with the message that opens: opening must be ordered low <= best <= high, and goes on to the percentile sentence. A computed closing out of order is reported as a result; a stated opening is checked on entry, with no reordering.'),
  ('prms', 'advanced', 'final', null, 27, 'A reconciliation period has additions and revisions but carries no production (rec-no-production). What replacement ratio and life index are printed?', '["0.000000 for both", "an infinite ratio, since additions are divided by zero production", "a refusal, since a Reserves period must carry production", "null for both, since the period carries no production"]'::jsonb, 3, 'Without production neither the replacement ratio nor the life index is printed: both are null (engine), and the reconciliation still closes. The engine divides by nothing; a period without production is a legitimate Reserves reconciliation.'),
  ('prms', 'advanced', 'final', null, 28, 'Reconcile names two SPE-PRMS 2018 sections in its basis. Which are they, and what does each cover?', '["4.2.5 and 4.2.6, the aggregation sections", "3.1.2.1 and 3.1.2.8, the economic test", "3.1.3.5 for reconciliation and technical revision, and 2.2.2.6 for reclassification without new information", "2.1.3.3 alone, the chance of commerciality"]'::jsonb, 2, 'The reconcile basis cites SPE-PRMS 2018 3.1.3.5 (reconciliation, technical revision) and 2.2.2.6 (a reclassification without new information leaves the distribution unchanged). 4.2.5 and 4.2.6 are cited for aggregation; 3.1.2.1 and 3.1.2.8 for the economic test; 2.1.3.3 for the chance of commerciality.'),
  ('prms', 'advanced', 'final', null, 29, 'On EKN-1, what are the canonical economic limits of the low and the high cases?', '["Low 2037 with 3 cut; high 2041, the last year of the forecast, with 0 cut", "Low 2033 with 7 trailing years cut; high 2040 with 0 cut", "Low 2040 with 0 cut; high 2033 with 7 cut", "Low and high both 2037"]'::jsonb, 1, 'The engine returns 2033 with 7 trailing years cut for the low case and 2040 with 0 years cut for the high case, which reaches the licence expiry (engine). 2037 with 3 cut is the best case; 2041 is the last forecast year and lies beyond the licence; the cases do not share a limit.'),
  ('prms', 'advanced', 'final', null, 30, 'What does the canonical trailing trim look at in each year?', '["Revenue less royalty less opex; tax, allowances and abandonment play no part", "The net cash flow after tax in that year, including the allowances and the abandonment", "The cumulative net cash flow before tax and abandonment", "The discounted net cash flow at the stated discount rate"]'::jsonb, 0, 'The trim cuts a trailing year whose revenue less royalty less opex is below 0, keeping capital years and a year at exactly 0. Tax and allowances enter the economic test; the cumulative before tax and abandonment is the PRMS peak; the trim reads no discounting.'),
  ('prms', 'advanced', 'final', null, 31, 'Under the PRMS cumulative peak, when do interim negative years count against the limit?', '["Always: the first negative year ends the field''s life", "Only when later positive years more than offset them", "Never: interim years are ignored and only the last year is read", "Only when they fall after the licence expiry"]'::jsonb, 1, 'The PRMS rule places the limit at the cumulative maximum, so interim negative years are carried through only when later positive years more than offset them; otherwise the cumulative never regains its peak and the limit stays at the peak year. The first negative year alone ends nothing; the last year alone is the trim''s reading; the licence is a separate cut.'),
  ('prms', 'advanced', 'final', null, 32, 'Development is planned 8 years out, and the caller states that the longer wait is justified; every other criterion is met. Which class results?', '["Contingent Resources: 8 years is beyond the five-year benchmark whatever justification is stated", "A refusal: a time-frame above 5 years must be left out of the stated commerciality facts", "Contingent Resources, sub-class development-on-hold", "Reserves: the time-frame is met because the longer time-frame is stated as justified"]'::jsonb, 3, 'The engine reads the time-frame as met within 5 years, or later when a longer time-frame is stated as justified (PRMS 2.1.2.3, a recommended benchmark): 8 years, justified, gives Reserves (engine). The benchmark yields to a stated justification, nothing is refused, and no Contingent sub-class applies.'),
  ('prms', 'advanced', 'final', null, 33, 'A prospect states a chance of geologic discovery of 0 and a chance of development of 50 percent. What does the engine return?', '["Undiscovered Unrecoverable, since no accumulation can be found when the chance of discovery is 0", "Prospective Resources, sub-class prospect, with a chance of commerciality of 0.000000", "A refusal: the chance of geologic discovery must be above 0", "Prospective Resources with a chance of commerciality of 50.000000, the chance of development alone"]'::jsonb, 1, 'Pc = Pg x Pd = 0.000000, and the class is still Prospective Resources, sub-class prospect (engine): a chance of 0 is a boundary the engine accepts. Unrecoverable follows from having no recovery project; 0 is inside the accepted range; Pd alone is the chance for a discovered project.'),
  ('prms', 'advanced', 'final', null, 34, 'Which reading does the engine state for its economic limit, and what alternative does it name?', '["The PRMS cumulative peak, checked against the trim; the alternative is the trim", "The licence expiry; the alternative is the last forecast year", "The first year of negative net cash flow after tax; the alternative is the last", "The canonical trailing trim, checked against the PRMS peak and refused where they disagree; the alternative is the limit placed at the PRMS cumulative peak"]'::jsonb, 3, 'Reading four: the canonical trailing trim is the economic limit, checked against the PRMS peak and refused where they disagree, and the alternative named is the limit placed at the PRMS cumulative peak. The peak is the check; the licence is a separate cut; and the trim reads revenue less royalty less opex before tax.'),
  ('prms', 'advanced', 'final', null, 35, 'A commercial discovery was declared 2 years ago on class-nigeria-fdp-2, and 12 years ago on EKN-1. What do the engine''s Nigerian notes say about the field development plan?', '["At both, the period has passed, since the plan was due on the very day the declaration was made to the Commission", "At both, the plan is still due, since s.79(1) sets no end", "At 2 years the plan is still due within the period; at 12 years the two-year period has passed", "The class of EKN-1 moves to Contingent Resources once the two-year period has passed without a plan"]'::jsonb, 2, 'PIA 2021 s.79(1) gives two years from a commercial discovery declaration: 2 years is inside the period and at 12 years the engine notes that the two-year period has passed. The notes are printed beside the class and leave it unchanged; EKN-1 stays Reserves.'),
  ('prms', 'advanced', 'final', null, 36, 'The Act''s interpretation section prints "Significant crude oil discovery" with a capital S and "significant gas discovery" without one. How does the course quote them?', '["Both with a capital S, for consistency", "Both in lower case, since the gazette capital is a typographical slip the course corrects", "In the course''s own words only, since the Act may not be quoted", "As printed, each with its own capital"]'::jsonb, 3, 'The course quotes public texts exactly, a spelling or a capital included, so each definition keeps the capital the Act prints. It corrects nothing in a quotation, and the Act is a public Nigerian law that the course quotes with citation.'),
  ('prms', 'advanced', 'final', null, 37, 'Why does the course place no reliance on the Commission''s posted copy of the Acreage Management and Petroleum (Drilling and Production) Regulation, 2024?', '["Its posted copy prints placeholders for its instrument and gazette numbers", "It was revoked by S.I. No. 37 of 2023", "It is sold and was not read", "It sets reserves booking rules the engine does not apply"]'::jsonb, 0, 'The posted copy prints placeholders where its instrument and gazette numbers belong, so the course does not rely on it. S.I. No. 37 of 2023 is an earlier instrument on significant discoveries; the copy is posted by the Commission; and no Nigerian booking rule was found at all.'),
  ('prms', 'advanced', 'final', null, 38, 'What does DEFAULTS.PSD_TOLERANCE of 1e-9 set?', '["The tolerance a reconciliation closes within when none is stated", "The smallest chance of commerciality the engine accepts", "How far the Cholesky factor may miss a stated correlation matrix before the matrix is refused", "The largest sampling error allowed before a Monte Carlo run is repeated"]'::jsonb, 2, 'PSD_TOLERANCE is an engine convention for the positive semidefinite check on a stated correlation. A reconciliation tolerance is a required input with no default; chances run from 0 to 100; and a seeded run is never repeated to shrink its error.'),
  ('prms', 'advanced', 'final', null, 39, 'From which edition was the English text of SPE-PRMS 2018 read for this course?', '["The SPE-hosted English-Chinese edition (Version 2023 V1.0, developed from PRMS 2018 V1.0), whose English is the 2018 text", "The 2022 edition, which revised the section numbers", "The paid 2022 Guidelines, which reprint the whole standard", "A summary on the NUPRC site"]'::jsonb, 0, 'The English text was read from the SPE-hosted English-Chinese edition, whose English is the 2018 text, and the section numbers are the 2018 numbers. The standard read is the 2018 text, with its 2019 to 2022 errata checked; the 2022 Guidelines are sold and were not read; the Commission''s site was read for its own release and regulations.'),
  ('prms', 'advanced', 'final', null, 40, 'The Commission hosts S.I. No. 37 of 2023 under a file name that reads "Significant Crude Oil and Gas Recovery Regulations". Which title does the course cite?', '["The file name, since the Commission''s own hosting is authoritative over the gazette", "The gazette title, the Significant Crude Oil and Gas Discovery Regulations, 2023", "Both, as two separate regulations made under the Act in 2023, one on discovery and one on recovery", "Neither: the course cites the PIA 2021 alone"]'::jsonb, 1, 'The gazette title is the Significant Crude Oil and Gas Discovery Regulations, 2023 (S.I. No. 37 of 2023, Official Gazette No. 111, Vol. 110, 20 June 2023), and the course cites it. The file name is a quirk of the hosting; there is one instrument; and the course quotes its regulations 3 to 7.'),
  ('prms', 'advanced', 'final', null, 41, 'How does the engine print money inside a reason?', '["Rounded to the cent, half away from zero, with trailing zeros dropped; every numeric field keeps full precision", "To six decimals, as every quantity is printed", "Rounded to the nearest thousand", "Truncated to whole units"]'::jsonb, 0, 'Inside a message the engine prints money rounded to the cent, half away from zero, trailing zeros dropped (156927914.66 in the EKN-1 low-case reason); a computed quantity or percentage prints to six decimals, trailing zeros dropped; and every numeric field keeps full precision. It neither rounds to thousands nor truncates.'),
  ('prms', 'advanced', 'final', null, 42, 'Which course of the academy owns distributions, correlation and Monte Carlo as a subject?', '["The uncertainty course; this engine applies the canonical seeded sampler of lib/stats to aggregation", "This course, whose aggregation module teaches sampling from first principles", "The cashflow course", "The reservoircalc course"]'::jsonb, 0, 'Distributions, correlation and Monte Carlo as a subject belong to the uncertainty course, and this engine applies the canonical sampler of lib/stats to aggregation without re-teaching it. The cashflow course owns the ledger, discounting and NPV; reservoircalc owns volumetrics.');
